import { useState, useEffect } from 'react';
import axios from 'axios';

const formatPhone = (value) => {
  let raw = value.replace(/[^\d+]/g, '');
  if (!raw.startsWith('+7')) {
    if (raw.startsWith('8')) raw = '+7' + raw.slice(1);
    else if (raw.startsWith('7')) raw = '+7' + raw.slice(1);
    else if (raw.length > 0) raw = '+7' + raw;
  }
  raw = raw.slice(0, 12);
  let formatted = '+7';
  if (raw.length > 2) formatted += ' (' + raw.slice(2, 5);
  if (raw.length > 5) formatted += ') ' + raw.slice(5, 8);
  if (raw.length > 8) formatted += '-' + raw.slice(8, 10);
  if (raw.length > 10) formatted += '-' + raw.slice(10, 12);
  return formatted;
};

const cleanPhone = (formatted) => {
  const digits = formatted.replace(/[^\d+]/g, '');
  if (digits.startsWith('+7')) return digits.slice(0, 12);
  if (digits.startsWith('8')) return '+7' + digits.slice(1, 11);
  if (digits.startsWith('7')) return '+7' + digits.slice(1, 11);
  return digits;
};

const UserManager = () => {
  const [users, setUsers] = useState([]);
  const [roles, setRoles] = useState([]);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState({
    surname: '',
    name: '',
    patronymic: '',
    phone: '',
    password: '',
    roleId: '',
    vkId: '',
  });
  const [error, setError] = useState('');
  const [fieldErrors, setFieldErrors] = useState({});

  const fetchUsers = async () => {
    try {
      const res = await axios.get('/api/admin/users');
      setUsers(res.data);
    } catch {
      setError('Ошибка загрузки пользователей');
    }
  };

  const fetchRoles = async () => {
    try {
      const res = await axios.get('/api/admin/roles');
      setRoles(res.data);
    } catch {
      setError('Ошибка загрузки ролей');
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchRoles();
  }, []);

  const resetForm = () => {
    setForm({
      surname: '',
      name: '',
      patronymic: '',
      phone: '',
      password: '',
      roleId: '',
      vkId: '',
    });
    setEditingId(null);
    setError('');
    setFieldErrors({});
  };

  const validate = () => {
    const errors = {};
    if (!form.surname || form.surname.trim().length < 2) errors.surname = 'Минимум 2 символа';
    if (!form.name || form.name.trim().length < 2) errors.name = 'Минимум 2 символа';
    if (!form.phone || form.phone.trim().length === 0) errors.phone = 'Обязательное поле';
    if (!form.roleId) errors.roleId = 'Выберите роль';
    if (!editingId && (!form.password || form.password.length < 6)) errors.password = 'Минимум 6 символов';
    else if (form.password.length > 0 && form.password.length < 6) errors.password = 'Минимум 6 символов';
    const employeeRole = roles.find(r => r.name === 'employee');
    if (employeeRole && form.roleId == employeeRole.id && (!form.vkId || form.vkId.toString().trim() === ''))
      errors.vkId = 'Требуется для сотрудника';
    setFieldErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!validate()) return;

    // Очищаем телефон перед отправкой
    const dataToSend = { ...form, phone: cleanPhone(form.phone) };
    try {
      if (editingId) {
        await axios.put(`/api/admin/users/${editingId}`, dataToSend);
      } else {
        await axios.post('/api/admin/users', dataToSend);
      }
      resetForm();
      fetchUsers();
    } catch (err) {
      setError(err.response?.data?.message || 'Ошибка сохранения');
    }
  };

  const handleEdit = (user) => {
    setEditingId(user.id);
    setForm({
      surname: user.surname,
      name: user.name,
      patronymic: user.patronymic || '',
      phone: user.phone,  // из базы приходит уже чистый номер, просто покажем как есть (можно и форматировать)
      password: '',
      roleId: user.role?.id || user.roleId,
      vkId: user.vkId || '',
    });
    setFieldErrors({});
  };

  const handleDelete = async (id) => {
    if (window.confirm('Удалить пользователя?')) {
      await axios.delete(`/api/admin/users/${id}`);
      fetchUsers();
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === 'phone') {
      setForm(prev => ({ ...prev, phone: formatPhone(value) }));
    } else {
      setForm(prev => ({ ...prev, [name]: value }));
    }
    if (fieldErrors[name]) {
      setFieldErrors(prev => ({ ...prev, [name]: undefined }));
    }
  };

  const employeeRole = roles.find(r => r.name === 'employee');
  const showVkId = employeeRole && form.roleId == employeeRole.id;

  return (
    <div className="user-manager">
      <h2>Управление пользователями</h2>
      {error && <div className="error-message">{error}</div>}
      <form onSubmit={handleSubmit} className="user-form">
        <div className="form-group">
          <input name="surname" placeholder="Фамилия" value={form.surname} onChange={handleChange} required />
          {fieldErrors.surname && <span className="field-error">{fieldErrors.surname}</span>}
        </div>

        <div className="form-group">
          <input name="name" placeholder="Имя" value={form.name} onChange={handleChange} required />
          {fieldErrors.name && <span className="field-error">{fieldErrors.name}</span>}
        </div>

        <div className="form-group">
          <input name="patronymic" placeholder="Отчество" value={form.patronymic} onChange={handleChange} />
        </div>

        <div className="form-group">
          <input
            name="phone"
            type="tel"
            placeholder="+7 (___) ___-__-__"
            value={form.phone}
            onChange={handleChange}
            required
          />
          {fieldErrors.phone && <span className="field-error">{fieldErrors.phone}</span>}
        </div>

        <div className="form-group">
          <input name="password" type="password" placeholder={editingId ? 'Новый пароль (необяз.)' : 'Пароль'} value={form.password} onChange={handleChange} required={!editingId} />
          {fieldErrors.password && <span className="field-error">{fieldErrors.password}</span>}
        </div>

        <div className="form-group">
          <select name="roleId" value={form.roleId} onChange={handleChange} required>
            <option value="">Выберите роль</option>
            {roles.map(role => (
              <option key={role.id} value={role.id}>{role.name}</option>
            ))}
          </select>
          {fieldErrors.roleId && <span className="field-error">{fieldErrors.roleId}</span>}
        </div>

        {showVkId && (
          <div className="form-group">
            <input name="vkId" type="number" placeholder="ID ВКонтакте" value={form.vkId} onChange={handleChange} />
            {fieldErrors.vkId && <span className="field-error">{fieldErrors.vkId}</span>}
          </div>
        )}

        <div className="form-buttons">
          <button type="submit">{editingId ? 'Сохранить' : 'Создать'}</button>
          {editingId && <button type="button" onClick={resetForm}>Отмена</button>}
        </div>
      </form>

      <div style={{ overflowX: 'auto' }}>
        <table className="user-table">
          <thead>
            <tr>
              <th>ID</th><th>ФИО</th><th>Телефон</th><th>Роль</th><th>VK ID</th><th>Действия</th>
            </tr>
          </thead>
          <tbody>
            {users.map(u => (
              <tr key={u.id}>
                <td>{u.id}</td>
                <td>{u.surname} {u.name} {u.patronymic}</td>
                <td>{u.phone}</td>
                <td>{u.role?.name || '—'}</td>
                <td>{u.vkId || '-'}</td>
                <td>
                  <button onClick={() => handleEdit(u)} title="Редактировать">✏️</button>
                  <button onClick={() => handleDelete(u.id)} title="Удалить">🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default UserManager;
